  "dumka-weaving":               { name: "Dumka Weaving", state: "Andhra Pradesh", region: "Agency areas, AP/Telangana border", blurb: "Tribal dhokra-adjacent textile craft.", q: "Dumka weaving tribal textile", d: "Coarse handloom tribal weaves with geometric border bands" },
  "narayanpet-textile":          { name: "Narayanpet Textile", state: "Telangana", region: "Narayanpet, Mahabubnagar", blurb: "Cotton saris with dotted checks and durai borders.", q: "Narayanpet textile saree border weave", d: "Textured cotton with small checks and thick temple borders" },
